const fs=require('fs');let src=fs.readFileSync('assets/six-candy-rounds-engine.js','utf8');const q=new Function('Engine','motionReduced',src+';return {sixPickChanceRound,sixPickSugarRound,sixPickGapTemplate,sixMakeBoard,sixPlan,sixRoundClearBonus,sixRefillBoard};')(class{},false);let seed=Number(process.argv[3]||91237);const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);let sum=0,sq=0,roles=0,bonus=0,clear=0,refills=0,repairs=0;const N=Number(process.argv[2]||10000);for(let k=0;k<N;k++){const chance=q.sixPickChanceRound(random),sugar=q.sixPickSugarRound(random);let r=1,g,uid=0,collected=false;const drawn=new Set();function board(){const b=q.sixMakeBoard(10,chance===r?3:4,random,uid,{holes:q.sixPickGapTemplate(random,r)});g=b.grid;uid=b.lastId;if(!collected&&r===sugar){const a=g.flat().filter(t=>t&&t.number==null);a[Math.floor(random()*a.length)].sugar=true;}}board();const nums=Array.from({length:25},(_,i)=>i+1);for(let i=24;i>0;i--){let j=Math.floor(random()*(i+1));[nums[i],nums[j]]=[nums[j],nums[i]];}let total=0,pos=0;for(const n of [3,2,1,1,1]){const batch=nums.slice(pos,pos+n),present=new Set(g.flat().filter(t=>t?.number!=null).map(t=>t.number)),miss=batch.some(n=>!present.has(n));batch.forEach(n=>drawn.add(n));let p=q.sixPlan(g,batch);pos+=n;g=p.grid;total+=p.gain;roles+=p.gain-(p.cleared?10000:0);clear+=p.cleared?10000:0;collected||=p.sugarAward;if(p.advance){const b=q.sixRoundClearBonus(r);total+=b;bonus+=b;if(pos<8&&r<5){r++;board();}}else if(miss){const f=q.sixRefillBoard(g,chance===r?3:4,random,uid,drawn);g=f.grid;uid=f.lastId;refills++;repairs+=!!f.recolored.length;}}sum+=total;sq+=total*total;}console.log(JSON.stringify({N,seed:process.argv[3]||91237,mean:sum/N/100,se:Math.sqrt((sq/N-(sum/N)**2)/N)/100,roles:roles/N/100,bonus:bonus/N/100,clear:clear/N/100,refills,repairs}));
